import sys
from collections import defaultdict

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return

    n = int(data[0])
    dictionary = []
    for i in range(1, 1 + n):
        dictionary.append(data[i])

    # Build word pattern to words mapping
    pattern_to_words = defaultdict(list)
    for word in dictionary:
        pattern = []
        char_map = {}
        next_num = 0
        for ch in word:
            if ch not in char_map:
                char_map[ch] = next_num
                next_num += 1
            pattern.append(char_map[ch])
        pattern_tuple = tuple(pattern)
        pattern_to_words[pattern_tuple].append(word)

    # Process encrypted lines
    encrypted_lines = data[1 + n:]

    for line in encrypted_lines:
        line = line.strip()
        if not line:
            print()
            continue

        encrypted_words = line.split()

        # Try to find a valid mapping
        solution = find_solution(encrypted_words, pattern_to_words)

        if solution is None:
            # No solution - print all asterisks
            print(' '.join(['*' * len(word) for word in encrypted_words]))
        else:
            # Apply solution
            decrypted = []
            for ew in encrypted_words:
                mapped = []
                for ch in ew:
                    if ch in solution:
                        mapped.append(solution[ch])
                    else:
                        mapped.append('*')
                decrypted.append(''.join(mapped))
            print(' '.join(decrypted))

def find_solution(encrypted_words, pattern_to_words):
    if not encrypted_words:
        return {}

    # Get patterns for each encrypted word
    patterns = []
    for ew in encrypted_words:
        pattern = []
        char_map = {}
        next_num = 0
        for ch in ew:
            if ch not in char_map:
                char_map[ch] = next_num
                next_num += 1
            pattern.append(char_map[ch])
        patterns.append(tuple(pattern))

    # Get candidate words for each pattern
    candidates = []
    for p in patterns:
        if p in pattern_to_words:
            candidates.append(pattern_to_words[p])
        else:
            candidates.append(None)  # No matching pattern

    # Check if any candidate list is empty
    for c in candidates:
        if c is None or len(c) == 0:
            return None

    # Use backtracking to find a valid mapping
    mapping = {}  # encrypted char -> decrypted char
    reverse_mapping = {}  # decrypted char -> encrypted char

    result = backtrack(encrypted_words, candidates, 0, mapping, reverse_mapping, pattern_to_words)
    return result

def backtrack(encrypted_words, candidates, word_idx, mapping, reverse_mapping, pattern_to_words):
    if word_idx == len(encrypted_words):
        return mapping.copy()

    ew = encrypted_words[word_idx]
    cand_list = candidates[word_idx]

    for candidate in cand_list:
        # Try this candidate word
        new_mapping = mapping.copy()
        new_reverse = reverse_mapping.copy()
        consistent = True

        # Check if this candidate is consistent with current mapping
        temp_mapping = {}
        for i in range(len(ew)):
            e_char = ew[i]
            d_char = candidate[i]
            if e_char in new_mapping:
                if new_mapping[e_char] != d_char:
                    consistent = False
                    break
            else:
                if d_char in new_reverse:
                    if new_reverse[d_char] != e_char:
                        consistent = False
                        break
                else:
                    temp_mapping[e_char] = d_char
                    new_reverse[d_char] = e_char

        if not consistent:
            continue

        # Apply temporary mappings
        for e_char, d_char in temp_mapping.items():
            new_mapping[e_char] = d_char
            new_reverse[d_char] = e_char

        # Recurse
        result = backtrack(encrypted_words, candidates, word_idx + 1, new_mapping, new_reverse, pattern_to_words)
        if result is not None:
            return result

    return None

if __name__ == "__main__":
    main()
